    integer i;
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            sp <= 0;
            data_out <= 8'h00;
            for (i = 0; i < DEPTH; i = i + 1) begin
                stack_mem[i] <= 8'h00;
            end
        end else begin
            // Xử lý Push
            if (push && !full) begin
                stack_mem[sp] <= data_in;
                sp <= sp + 1;
            end
            // Xử lý Pop
            else if (pop && !empty) begin
                sp <= sp - 1;
