            CHECKSUM: begin
                frame_out = 8'hAA ^ latched_payload;
                frame_valid = 1'b1;
                next_state = EOF;
            end

            EOF: begin
                frame_out = 8'h55;
                frame_valid = 1'b1;
                next_state = IDLE;
            end

            default: begin
                next_state = IDLE;
            end
        endcase
