                    next_state = DONE;
                end else begin
                    next_cnt = cnt + 1'b1;
                end
            end

            DONE: begin
                delayed_out = 1'b1;
                next_state  = IDLE;
            end

            default: begin
                next_state = IDLE;
                next_cnt   = 8'd0;
            end
        endcase
    end

