        cs_ram = 1'b1;
        cs_rom = 1'b1;
        cs_io  = 1'b1;

        if (mem_en) begin
            case (addr[15:14])
                2'b00, 2'b01: begin
                    cs_ram = 1'b0; // Vùng 0x0000 - 0x7FFF
