module vga_sync_generator (
    input  wire       clk_25m,
    input  wire       rst,
    output reg        hsync,
    output reg        vsync,
    output reg        video_on,
    output reg [9:0]  pixel_x,
    output reg [9:0]  pixel_y
);

    // Thông số VGA 640x480 @ 60Hz
    parameter H_TOTAL = 800;
    parameter H_SYNC  = 96;
    parameter H_BACK  = 48;
    parameter H_ACT   = 640;
    parameter H_FRONT = 16;

    parameter V_TOTAL = 525;
    parameter V_SYNC  = 2;
    parameter V_BACK  = 33;
    parameter V_ACT   = 480;
    parameter V_FRONT = 10;

    // Các thanh ghi đếm
    reg [9:0] h_cnt;
    reg [9:0] v_cnt;

    // Logic bộ đếm ngang
    always @(posedge clk_25m or posedge rst) begin
        if (rst) begin
            h_cnt <= 10'd0;
        end else begin
            if (h_cnt == (H_TOTAL - 1))
                h_cnt <= 10'd0;
            else
                h_cnt <= h_cnt + 1'b1;
        end
    end

    // Logic bộ đếm dọc
    always @(posedge clk_25m or posedge rst) begin
        if (rst) begin
            v_cnt <= 10'd0;
        end else begin
            if (h_cnt == (H_TOTAL - 1)) begin
                if (v_cnt == (V_TOTAL - 1))
                    v_cnt <= 10'd0;
                else
                    v_cnt <= v_cnt + 1'b1;
            end
        end
    end

    // Logic tạo tín hiệu đồng bộ và video_on
    always @(posedge clk_25m or posedge rst) begin
        if (rst) begin
            hsync    <= 1'b1;
            vsync    <= 1'b1;
            video_on <= 1'b0;
            pixel_x  <= 10'd0;
            pixel_y  <= 10'd0;
        end else begin
            // HSYNC: Active low trong 96 chu kỳ đầu
            hsync <= (h_cnt < H_SYNC) ? 1'b0 : 1'b1;

            // VSYNC: Active low trong 2 dòng đầu
            vsync <= (v_cnt < V_SYNC) ? 1'b0 : 1'b1;

            // Video_on: Chỉ bật trong vùng hiển thị tích cực
            if ((h_cnt >= (H_SYNC + H_BACK)) && (h_cnt < (H_SYNC + H_BACK + H_ACT)) &&
                (v_cnt >= (V_SYNC + V_BACK)) && (v_cnt < (V_SYNC + V_BACK + V_ACT))) begin
                video_on <= 1'b1;
                pixel_x  <= h_cnt - (H_SYNC + H_BACK);
                pixel_y  <= v_cnt - (V_SYNC + V_BACK);
            end else begin
                video_on <= 1'b0;
                pixel_x  <= 10'd0;
                pixel_y  <= 10'd0;
