            3'b100: begin // XOR
                next_alu_out = a ^ b;
                next_carry = 1'b0;
            end
            3'b101: begin // NOT
                next_alu_out = ~a;
                next_carry = 1'b0;
            end
            3'b110: begin // Dịch trái
                next_alu_out = a << 1;
                next_carry = a[3]; // Bit bị đẩy ra ngoài
            end
            3'b111: begin // So sánh bằng
                next_alu_out = (a == b) ? 4'b0001 : 4'b0000;
                next_carry = 1'b0;
            end
            default: begin
                next_alu_out = 4'b0000;
                next_carry = 1'b0;
            end
        endcase
    end

