module can_tx (
    input wire clk,
    input wire reset,
    input wire [7:0] data_in,
    input wire send,
    output reg can_out,
    output reg busy
);

    // Định nghĩa trạng thái FSM
    parameter IDLE    = 2'b00;
    parameter SENDING = 2'b01;
    parameter DONE    = 2'b10;

    reg [1:0] state, next_state;
    reg [7:0] shift_reg;
    reg [2:0] bit_cnt;

    // Logic tuần tự: FSM và thanh ghi
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 8'h00;
            bit_cnt   <= 3'd0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    if (send) begin
                        shift_reg <= data_in;
                        bit_cnt   <= 3'd0;
                    end
                end
                SENDING: begin
                    shift_reg <= {1'b0, shift_reg[7:1]}; // Dịch phải LSB first
                    bit_cnt   <= bit_cnt + 1'b1;
                end
                default: begin
                    shift_reg <= shift_reg;
                    bit_cnt   <= bit_cnt;
                end
            endcase
        end
    end

    // Logic tổ hợp: Chuyển trạng thái và Output
    always @(*) begin
        // Giá trị mặc định để tránh latch
        next_state = state;
        can_out    = 1'b1; // CAN bus idle state is recessive (high)
        busy       = 1'b0;

        case (state)
            IDLE: begin
                busy = 1'b0;
                can_out = 1'b1;
                if (send)
                    next_state = SENDING;
