// Module: inv_word_mix_columns
// Standard: IEEE 1364-2001
// Description: Inverse MixColumns transformation for 32-bit word (AES standard)

module inv_word_mix_columns (
    input  wire [31:0] in,
    output wire [31:0] out
);

    // Function: xtime (multiplication by 2 in GF(2^8))
    function [7:0] xtime;
        input [7:0] x;
        begin
            xtime = (x & 8'h80) ? ((x << 1) ^ 8'h1B) : (x << 1);
        end
    endfunction

    // Function: mul_inv (multiplication in GF(2^8) for Inverse MixColumns coefficients)
    // Coefficients: {0E, 0B, 0D, 09}
    function [7:0] mul_inv;
        input [7:0] x;
        input [1:0] coeff_idx; // 0: 0E, 1: 0B, 2: 0D, 3: 09
        reg [7:0] x2, x4, x8;
        begin
            x2 = xtime(x);
            x4 = xtime(x2);
            x8 = xtime(x4);

            case (coeff_idx)
                2'd0: mul_inv = x8 ^ x4 ^ x2;       // 0E = 8 + 4 + 2
                2'd1: mul_inv = x8 ^ x2 ^ x;        // 0B = 8 + 2 + 1
                2'd2: mul_inv = x8 ^ x4 ^ x;        // 0D = 8 + 4 + 1
                2'd3: mul_inv = x8 ^ x;             // 09 = 8 + 1
                default: mul_inv = 8'h00;
            endcase
        end
    endfunction

    // Internal signals for byte splitting
    wire [7:0] b0, b1, b2, b3;
    assign b0 = in[31:24];
    assign b1 = in[23:16];
    assign b2 = in[15:8];
    assign b3 = in[7:0];

    // Inverse MixColumns Logic
    // Output byte i is a linear combination of input bytes
    // [0E 0B 0D 09]   [b0]
    // [09 0E 0B 0D] * [b1]
    // [0D 09 0E 0B]   [b2]
    // [0B 0D 09 0E]   [b3]

    assign out[31:24] = mul_inv(b0, 0) ^ mul_inv(b1, 1) ^ mul_inv(b2, 2) ^ mul_inv(b3, 3);
    assign out[23:16] = mul_inv(b0, 3) ^ mul_inv(b1, 0) ^ mul_inv(b2, 1) ^ mul_inv(b3, 2);
    assign out[15:8]  = mul_inv(b0, 2) ^ mul_inv(b1, 3) ^ mul_inv(b2, 0) ^ mul_inv(b3, 1);
    assign out[7:0]   = mul_inv(b0, 1) ^ mul_inv(b1, 2) ^ mul_inv(b2, 3) ^ mul_inv(b3, 0);

