    always @(posedge clk0_i or posedge rst0_i) begin
        if (rst0_i) begin
            sel_sync0 <= 1'b0;
            en_sync0  <= 1'b0;
            sel_q0    <= 1'b0;
            en_q0     <= 1'b0;
        end else begin
            sel_sync0 <= select;
            sel_q0    <= sel_sync0;
            en_sync0  <= enable;
            en_q0     <= en_sync0;
        end
    end

    // 2. Synchronize control signals to clk1 domain
    always @(posedge clk1_i or posedge rst1_i) begin
        if (rst1_i) begin
            sel_sync1 <= 1'b0;
            en_sync1  <= 1'b0;
            sel_q1    <= 1'b0;
            en_q1     <= 1'b0;
