// Description: Synchronous FIFO with full flag generation

module fifotwoflag (
    input wire clk,
    input wire rst_n,       // Reset tích cực mức thấp
    input wire wr_en,       // Tín hiệu cho phép ghi
    input wire rd_en,       // Tín hiệu cho phép đọc
    input wire [7:0] din,   // Dữ liệu đầu vào
    output reg [7:0] dout,  // Dữ liệu đầu ra
    output wire full,       // Cờ báo đầy
    output wire empty       // Cờ báo rỗng
);

    // Tham số cấu hình
    parameter DEPTH = 16;
    parameter ADDR_WIDTH = 4;

    // Bộ nhớ FIFO
    reg [7:0] mem [0:DEPTH-1];

    // Con trỏ đọc/ghi (thêm 1 bit để phân biệt full/empty)
    reg [ADDR_WIDTH:0] wr_ptr;
    reg [ADDR_WIDTH:0] rd_ptr;

    // Logic ghi dữ liệu
    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1) begin
                mem[i] <= 8'd0;
            end
            wr_ptr <= 0;
        end else if (wr_en && !full) begin
            mem[wr_ptr[ADDR_WIDTH-1:0]] <= din;
            wr_ptr <= wr_ptr + 1;
        end
    end

    // Logic đọc dữ liệu
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            dout <= 8'd0;
            rd_ptr <= 0;
        end else if (rd_en && !empty) begin
            dout <= mem[rd_ptr[ADDR_WIDTH-1:0]];
            rd_ptr <= rd_ptr + 1;
        end
