    always @(posedge clk_i or posedge reset_i) begin
        if (reset_i) begin
            current_state <= IDLE;
        end else begin
            current_state <= next_state;
        end
    end

    // Khối tổ hợp: Chuyển trạng thái (Next State Logic)
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (seq_in) next_state = S1;
