    always @(posedge clock or posedge reset) begin
        if (reset) begin
            current_state <= IDLE;
            last_winner   <= 1'b0;
        end else if (enable) begin
            current_state <= next_state;
            if (current_state == GRANT_0) last_winner <= 1'b0;
            else if (current_state == GRANT_1) last_winner <= 1'b1;
        end else begin
            current_state <= IDLE;
        end
    end

