module adv_dbg_if_cpu1_crc32 (
    input wire clk,
    input wire data,
    input wire enable,
    input wire shift,
    input wire clr,
    input wire rst,
    output wire [31:0] crc_out,
    output wire serial_out
);

    // Register to store the 32-bit CRC value
    reg [31:0] crc_reg;

    // CRC-32 Polynomial (Reflected): 0xEDB88320
    // Standard for IEEE 802.3 and many debug interfaces
    parameter CRC_POLY = 32'hEDB88320;
    parameter CRC_INIT = 32'hFFFFFFFF;

    // Sequential Logic for CRC update and Shift operation
    always @(posedge clk or posedge rst) begin
        if (rst) begin
            // Asynchronous Reset
            crc_reg <= CRC_INIT;
        end
        else if (clr) begin
            // Synchronous Clear
            crc_reg <= CRC_INIT;
        end
        else if (shift) begin
            // Shift Mode: Acts as a standard shift register
            // Data enters from MSB, shifting towards LSB
            crc_reg <= {data, crc_reg[31:1]};
        end
        else if (enable) begin
            // CRC Calculation Mode (Backward/Reflected LFSR)
            // Feedback is XOR of LSB and incoming data
            if (crc_reg[0] ^ data) begin
                crc_reg <= (crc_reg >> 1) ^ CRC_POLY;
            end
            else begin
                crc_reg <= (crc_reg >> 1);
            end
        end
        else begin
            // Default: Maintain state to prevent latches
            crc_reg <= crc_reg;
        end
    end

    // Output Assignments
    // Full 32-bit parallel output
    assign crc_out = crc_reg;

    // Serial output (LSB is shifted out first in backward CRC)
    assign serial_out = crc_reg[0];

